            char b = Character.toLowerCase(s.charAt(right)); 

            if (a != b) { 
                System.out.println("false"); 
                sc.close(); 
                return; 
            } 

            left++; 
            right--; 
        } 

        System.out.println("true"); 
        sc.close(); 
    } 
