import java.util.*; 

public class Solution { 

    static class TimeMap { 
        private Map<String, List<Integer>> timestamps = new 
HashMap<>(); 
        private Map<String, List<String>> values = new HashMap<>(); 

        public void set(String key, String value, int timestamp) { 
            timestamps.computeIfAbsent(key, k -> new ArrayList<>()) 
                      .add(timestamp); 

            values.computeIfAbsent(key, k -> new ArrayList<>()) 
                  .add(value); 
        } 

        public String get(String key, int timestamp) { 
            if (!timestamps.containsKey(key)) { 
                return "EMPTY"; 
            } 

            List<Integer> times = timestamps.get(key); 
            List<String> vals = values.get(key); 

            int left = 0; 
            int right = times.size() - 1; 
            int result = -1; 

            while (left <= right) { 
                int mid = left + (right - left) / 2; 

                if (times.get(mid) <= timestamp) { 
                    result = mid; 
                    left = mid + 1; 
                } else { 
                    right = mid - 1; 
                } 
            } 

            return result == -1 ? "EMPTY" : vals.get(result); 
        } 
    } 

    public static void main(String[] args) { 
        Scanner sc = new Scanner(System.in); 

        int q = sc.nextInt(); 
        TimeMap timeMap = new TimeMap(); 
        StringBuilder output = new StringBuilder(); 

        for (int i = 0; i < q; i++) { 
            String operation = sc.next(); 

            if (operation.equals("SET")) { 
                String key = sc.next(); 
                String value = sc.next(); 
                int timestamp = sc.nextInt(); 
                timeMap.set(key, value, timestamp); 
            } else if (operation.equals("GET")) { 
                String key = sc.next(); 
                int timestamp = sc.nextInt(); 
                output.append(timeMap.get(key, timestamp)).append('\n'); 
            } 
        } 

        System.out.print(output); 
        sc.close(); 
    } 
}

