        for (int num : nums) { 
            if (currentSum + num > maxSum) { 
                subarrays++; 
                currentSum = 0; 
            } 

            currentSum += num; 

            if (subarrays > k) { 
                return false; 
            } 
        } 

        return true; 
    } 
