        if (root == null) { 
            System.out.println("EMPTY"); 
        } else { 
            printLevelOrder(root, n); 
        } 

        sc.close(); 
    } 

    private static Node buildTree(int[] values) { 
        if (values[0] == -1) { 
            return null; 
        } 

        Node root = new Node(values[0]); 
        Queue<Node> queue = new LinkedList<>(); 
        queue.offer(root); 

        int index = 1; 

        while (!queue.isEmpty() && index < values.length) { 
            Node current = queue.poll(); 

            if (index < values.length) { 
                if (values[index] != -1) { 
                    current.left = new Node(values[index]); 
                    queue.offer(current.left); 
                } 
                index++; 
            } 

            if (index < values.length) { 
                if (values[index] != -1) { 
                    current.right = new Node(values[index]); 
                    queue.offer(current.right); 
                } 
                index++; 
            } 
        } 

        return root; 
    } 

    private static void invertTree(Node root) { 
        if (root == null) { 
            return; 
        } 

        Node temp = root.left; 
        root.left = root.right; 
        root.right = temp; 

        invertTree(root.left); 
        invertTree(root.right); 
    } 

    private static void printLevelOrder(Node root, int n) { 
        Queue<Node> queue = new LinkedList<>(); 
        List<String> result = new ArrayList<>(); 

        result.add(String.valueOf(root.value)); 
        queue.offer(root); 

        while (!queue.isEmpty() && result.size() < n) { 
            Node current = queue.poll(); 

            Node left = current.left; 
            Node right = current.right; 

            result.add(left == null ? "-1" : String.valueOf(left.value)); 
            if (left != null) { 
                queue.offer(left); 
            } 

            if (result.size() < n) { 
                result.add(right == null ? "-1" : String.valueOf(right.value)); 
                if (right != null) { 
                    queue.offer(right); 
                } 
            } 
        } 

        while (result.size() < n) { 
            result.add("-1"); 
        } 

        System.out.println(String.join(" ", result)); 
    } 
}

