public class Solution { 

    static class Node { 
        int val; 
        Node left, right; 

        Node(int val) { 
            this.val = val; 
        } 
    } 

    static int preorderIndex; 
    static Map<Integer, Integer> inorderMap; 

    public static void main(String[] args) { 
        Scanner sc = new Scanner(System.in); 
        StringBuilder input = new StringBuilder(); 

        while (sc.hasNextLine()) { 
            input.append(sc.nextLine()).append("\n"); 
        } 

        String text = input.toString(); 

        Matcher matcher = Pattern.compile("-?\\d+").matcher(text); 
        List<Integer> numbers = new ArrayList<>(); 

        while (matcher.find()) { 
            numbers.add(Integer.parseInt(matcher.group())); 
        } 

        if (numbers.isEmpty()) { 
            sc.close(); 
            return; 
        } 

        int n = numbers.size() / 2; 

        int[] preorder = new int[n]; 
        int[] inorder = new int[n]; 

        for (int i = 0; i < n; i++) { 
            preorder[i] = numbers.get(i); 
            inorder[i] = numbers.get(n + i); 
        } 

        preorderIndex = 0; 
        inorderMap = new HashMap<>(); 

        for (int i = 0; i < n; i++) { 
            inorderMap.put(inorder[i], i); 
        } 

        Node root = buildTree(preorder, 0, n - 1); 
        printLevelOrder(root); 

        sc.close(); 
    } 

    static Node buildTree(int[] preorder, int left, int right) { 
        if (left > right) { 
            return null; 
        } 

        int value = preorder[preorderIndex++]; 
        Node root = new Node(value); 

        int mid = inorderMap.get(value); 

        root.left = buildTree(preorder, left, mid - 1); 
        root.right = buildTree(preorder, mid + 1, right); 

        return root; 
    } 

    static void printLevelOrder(Node root) { 
        Queue<Node> queue = new LinkedList<>(); 
        List<String> result = new ArrayList<>(); 

        queue.offer(root); 
        result.add(String.valueOf(root.val)); 

        while (!queue.isEmpty()) { 
            Node current = queue.poll(); 

            if (current.left != null) { 
                result.add(String.valueOf(current.left.val)); 
                queue.offer(current.left); 
            } else { 
                result.add("-1"); 
            } 

            if (current.right != null) { 
                result.add(String.valueOf(current.right.val)); 
                queue.offer(current.right); 
            } else { 
                result.add("-1"); 
            } 
        } 

        while (!result.isEmpty() && result.get(result.size() - 1).equals("-1")) { 
            result.remove(result.size() - 1); 
        } 

        System.out.println(String.join(" ", result)); 
    } 
}

