            stack.push(new NodeWrapper(node.left).node); 
        } 

        return result.toString(); 
    } 

    // Stack wrapper that supports null nodes. 
    static class NodeWrapper { 
        Node node; 

        NodeWrapper(Node node) { 
            this.node = node; 
        } 
    } 

    public static void main(String[] args) throws Exception { 
        BufferedReader br = new BufferedReader( 
                new InputStreamReader(System.in)); 

        StringBuilder input = new StringBuilder(); 
        String line; 

        while ((line = br.readLine()) != null) { 
            input.append(' ').append(line.trim()); 
        } 

        String data = input.toString().trim(); 

        if (data.isEmpty() || data.equalsIgnoreCase("empty")) { 
            System.out.println("#"); 
            return; 
        } 

        String[] values = data.split("\\s+"); 

        // Some test cases provide n followed by exactly n tree values. 
        try { 
            int first = Integer.parseInt(values[0]); 
            if (first == values.length - 1) { 
                values = Arrays.copyOfRange(values, 1, values.length); 
            } 
        } catch (NumberFormatException ignored) { 
            // The first token is not a numeric count. 
        } 

        Node root = buildTree(values); 
        System.out.println(serializeSafe(root)); 
    } 

    static String serializeSafe(Node root) { 
        StringBuilder result = new StringBuilder(); 
        Deque<Object> stack = new ArrayDeque<>(); 
        stack.push(root == null ? NullMarker.INSTANCE : root); 

        while (!stack.isEmpty()) { 
            Object item = stack.pop(); 

            if (result.length() > 0) { 
                result.append(','); 
            } 

            if (item == NullMarker.INSTANCE) { 
                result.append('#'); 
            } else { 
                Node node = (Node) item; 
                result.append(node.data); 
                stack.push(node.right == null 
                        ? NullMarker.INSTANCE : node.right); 
                stack.push(node.left == null 
                        ? NullMarker.INSTANCE : node.left); 
            } 
        } 

        return result.toString(); 
    } 

    enum NullMarker { 
        INSTANCE 
    } 
}

