public class Solution {
    static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        String word;
    }

    static class WordSearch {
        private final TrieNode root = new TrieNode();
        private final Set<String> result = new TreeSet<>();

        void insert(String word) {
            TrieNode cur = root;
            for (char ch : word.toCharArray()) {
                int idx = ch - 'a';
                if (cur.children[idx] == null) {
                    cur.children[idx] = new TrieNode();
                }
                cur = cur.children[idx];
            }
            cur.word = word;
        }

        public List<String> findWords(char[][] board, String[] words) {
            for (String word : words) {
                insert(word);
            }

            int rows = board.length;
            int cols = board[0].length;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    dfs(board, r, c, root);
                }
            }

            return new ArrayList<>(result);
        }

        private void dfs(char[][] board, int r, int c, TrieNode node) {
            char ch = board[r][c];
            if (ch == '#' || node.children[ch - 'a'] == null) return;

            node = node.children[ch - 'a'];
            if (node.word != null) {
                result.add(node.word);
            }

            board[r][c] = '#';
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];
                if (nr >= 0 && nr < board.length && nc >= 0 && nc < board[0].length) {
                    dfs(board, nr, nc, node);
                }
            }
            board[r][c] = ch;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        while (line != null && line.trim().isEmpty()) line = br.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        char[][] board = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            line = br.readLine();
            while (line != null && line.trim().isEmpty()) line = br.readLine();
            st = new StringTokenizer(line);
            for (int c = 0; c < cols; c++) {
                board[r][c] = st.nextToken().charAt(0);
            }
        }

        line = br.readLine();
        while (line != null && line.trim().isEmpty()) line = br.readLine();
        int numberOfWords = Integer.parseInt(line.trim());
        String[] words = new String[numberOfWords];
        for (int i = 0; i < numberOfWords; i++) {
            words[i] = br.readLine().trim();
        }

        WordSearch solver = new WordSearch();
        List<String> foundWords = solver.findWords(board, words);

        if (foundWords.isEmpty()) {
            System.out.println("[]");
        } else {
            for (String word : foundWords) {
                System.out.println(word);
            }
        }
    }
}

