        if (initialLine != null && !initialLine.trim().isEmpty()) { 
            for (String token : initialLine.trim().split("\\s+")) { 
                add(Integer.parseInt(token)); 
            } 
        } 

        StringBuilder output = new StringBuilder(); 

        if (futureLine != null && !futureLine.trim().isEmpty()) { 
            for (String token : futureLine.trim().split("\\s+")) { 
                add(Integer.parseInt(token)); 

                if (output.length() > 0) { 

                    output.append('\n'); 
                } 

                if (minHeap.size() < k) { 
                    output.append("null"); 
                } else { 
                    output.append(minHeap.peek()); 
                } 
            } 
        } 

        System.out.println(output); 
    } 
