        Map<Integer, Set<Integer>> following = new HashMap<>(); 
        int time = 0; 

        public void postTweet(int userId, int tweetId) { 
            tweets.putIfAbsent(userId, new ArrayList<>()); 
            tweets.get(userId).add(new Tweet(tweetId, time++)); 
        } 

        public List<Integer> getNewsFeed(int userId) { 
            PriorityQueue<Tweet> pq = 
                new PriorityQueue<>((a, b) -> b.time - a.time); 

            addTweets(pq, userId); 

            for (int user : following.getOrDefault(userId, new 
HashSet<>())) { 
                addTweets(pq, user); 
            } 


            List<Integer> feed = new ArrayList<>(); 

            while (!pq.isEmpty() && feed.size() < 10) { 
                feed.add(pq.poll().id); 
            } 

            return feed; 
        } 

        private void addTweets(PriorityQueue<Tweet> pq, int userId) { 
            List<Tweet> list = tweets.getOrDefault(userId, new 
ArrayList<>()); 

            for (int i = Math.max(0, list.size() - 10); i < list.size(); i++) { 
                pq.offer(list.get(i)); 
            } 
        } 

        public void follow(int followerId, int followeeId) { 
            if (followerId == followeeId) return; 

            following.putIfAbsent(followerId, new HashSet<>()); 
            following.get(followerId).add(followeeId); 

        } 

        public void unfollow(int followerId, int followeeId) { 
            following.getOrDefault(followerId, new HashSet<>()) 
                     .remove(followeeId); 
        } 
    } 

