import java.util.*;
import java.util.regex.*;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        StringBuilder fullInput = new StringBuilder();
        while (sc.hasNextLine()) {
            fullInput.append(sc.nextLine()).append("\n");
        }
        String s = fullInput.toString().trim();
        if (s.isEmpty()) return;

        List<Integer> candidatesList = new ArrayList<>();
        int target = 0;

        Pattern candPattern = Pattern.compile("candidates\\s*=\\s*\\[(.*?)\\]");
        Pattern targPattern = Pattern.compile("target\\s*=\\s*(-?\\d+)");
        Matcher candMatcher = candPattern.matcher(s);
        Matcher targMatcher = targPattern.matcher(s);

        if (candMatcher.find() && targMatcher.find()) {
            String inside = candMatcher.group(1).trim();
            if (!inside.isEmpty()) {
                String[] parts = inside.split(",");
                for (String p : parts) {
                    candidatesList.add(Integer.parseInt(p.trim()));
                }
            }
            target = Integer.parseInt(targMatcher.group(1).trim());
        } else {
            Scanner sc2 = new Scanner(s);
            if (sc2.hasNextInt()) {
                int first = sc2.nextInt();
                List<Integer> nums = new ArrayList<>();
                nums.add(first);
                while (sc2.hasNextInt()) {
                    nums.add(sc2.nextInt());
                }
                if (nums.size() >= 2) {
                    target = nums.get(nums.size() - 1);
                    candidatesList = nums.subList(0, nums.size() - 1);
                }
            }
        }

        int[] candidates = new int[candidatesList.size()];
        for (int i = 0; i < candidatesList.size(); i++) {
            candidates[i] = candidatesList.get(i);
        }

        Arrays.sort(candidates);
        List<List<Integer>> result = new ArrayList<>();
        backtrack(candidates, target, 0, new ArrayList<>(), result);

        if (result.isEmpty()) {
            System.out.println("[]");
        } else {
            for (List<Integer> combination : result) {
                System.out.println(combination.toString().replace(" ", ""));
            }
        }
    }

    private static void backtrack(int[] candidates, int remain, int start, List<Integer> current, List<List<Integer>> result) {
        if (remain == 0) {
            result.add(new ArrayList<>(current));
            return;
        }

        for (int i = start; i < candidates.length; i++) {
            if (candidates[i] > remain) break;
            current.add(candidates[i]);
            backtrack(candidates, remain - candidates[i], i, current, result);
            current.remove(current.size() - 1);
        }
    }
}

