public class Solution { 
    static int m, n; 
    static char[][] board; 
    static String word; 

    static boolean dfs(int r, int c, int index) { 
        if (index == word.length()) { 
            return true; 
        } 

        if (r < 0 || r >= m || c < 0 || c >= n 
                || board[r][c] != word.charAt(index)) { 
            return false; 
        } 

        char temp = board[r][c]; 
        board[r][c] = '#'; 

        boolean found = dfs(r + 1, c, index + 1) 
                     || dfs(r - 1, c, index + 1) 
                     || dfs(r, c + 1, index + 1) 
                     || dfs(r, c - 1, index + 1); 

        board[r][c] = temp; 

        return found; 
    } 

    public static void main(String[] args) { 
