import java.util.*; 

public class Solution { 
    HashMap<Integer, String> mp = new HashMap<>(); 
    List<String> res = new ArrayList<>(); 

    public Solution() { 
        mp.put(2, "abc"); 
        mp.put(3, "def"); 
        mp.put(4, "ghi"); 
        mp.put(5, "jkl"); 
        mp.put(6, "mno"); 
        mp.put(7, "pqrs"); 
        mp.put(8, "tuv"); 
        mp.put(9, "wxyz"); 
    } 

    public List<String> letterCombinations(String digits) { 
        res.clear(); 

        if (digits == null || digits.isEmpty() 
                || digits.equalsIgnoreCase("empty string")) { 
            return res; 
        } 

        StringBuilder sb = new StringBuilder(); 
        dfs(digits, 0, sb); 

        return res; 
    } 

    private void dfs(String str, int idx, StringBuilder sb) { 
        if (idx == str.length()) { 
            res.add(sb.toString()); 
            return; 
        } 

        int num = str.charAt(idx) - '0'; 
        String letters = mp.get(num); 

        if (letters == null) { 
            return; 
        } 

        for (char c : letters.toCharArray()) { 
            sb.append(c); 
            dfs(str, idx + 1, sb); 
            sb.deleteCharAt(sb.length() - 1); 
        } 
    } 

    public static void main(String[] args) { 
        Scanner sc = new Scanner(System.in); 
        String digits = sc.hasNextLine() ? sc.nextLine().trim() : ""; 

        Solution sol = new Solution(); 
        List<String> result = sol.letterCombinations(digits); 

        System.out.println(result.toString().replace(" ", "")); 

        sc.close(); 
    } 
}

