import java.util.*; 

public class Solution { 
    static int n; 
    static List<List<String>> solutions = new ArrayList<>(); 
    static char[][] board; 

    static void solve(int row, boolean[] cols, 
                      boolean[] diag1, boolean[] diag2) { 
        if (row == n) { 
            List<String> arrangement = new ArrayList<>(); 

            for (int i = 0; i < n; i++) { 
                arrangement.add(new String(board[i])); 
            } 

            solutions.add(arrangement); 
            return; 
        } 

        for (int col = 0; col < n; col++) { 
            int d1 = row - col + n - 1; 
            int d2 = row + col; 

            if (cols[col] || diag1[d1] || diag2[d2]) { 
                continue; 
            } 

            board[row][col] = 'Q'; 
            cols[col] = true; 
            diag1[d1] = true; 
            diag2[d2] = true; 

            solve(row + 1, cols, diag1, diag2); 

            board[row][col] = '.'; 
            cols[col] = false; 
            diag1[d1] = false; 
            diag2[d2] = false; 
        } 
    } 

    public static void main(String[] args) { 
        Scanner sc = new Scanner(System.in); 

        n = sc.nextInt(); 
        board = new char[n][n]; 

        for (int i = 0; i < n; i++) { 
            Arrays.fill(board[i], '.'); 
        } 

        solve(n > 0 ? 0 : n, 
              new boolean[n], 
              new boolean[2 * n - 1], 
              new boolean[2 * n - 1]); 

        System.out.println(solutions.size() + 
                (solutions.size() == 1 ? " solution" : " solutions")); 

        sc.close(); 
    } 
}

