        grid[row][col] = 0; 

        int area = 1; 
        area += dfs(row + 1, col); 
        area += dfs(row - 1, col); 
        area += dfs(row, col + 1); 
        area += dfs(row, col - 1); 

        return area; 
    } 

    public static void main(String[] args) { 
        Scanner sc = new Scanner(System.in); 

        m = sc.nextInt(); 
        n = sc.nextInt(); 
        grid = new int[m][n]; 

        for (int i = 0; i < m; i++) { 
            int col = 0; 

            while (col < n && sc.hasNext()) { 
                String token = sc.next(); 

                for (int k = 0; k < token.length() && col < n; k++) { 
                    char ch = token.charAt(k); 

                    if (ch == '0' || ch == '1') { 
                        grid[i][col++] = ch - '0'; 
                    } 
                } 
            } 
        } 

        int maxArea = 0; 

        for (int i = 0; i < m; i++) { 
            for (int j = 0; j < n; j++) { 
                if (grid[i][j] == 1) { 
                    maxArea = Math.max(maxArea, dfs(i, j)); 
                } 
            } 
        } 

        System.out.println(maxArea); 
        sc.close(); 
    } 
}

