public class Solution { 
    public static void main(String[] args) { 
        Scanner sc = new Scanner(System.in); 
        List<int[]> inputRows = new ArrayList<>(); 
        final int INF = Integer.MAX_VALUE; 

        while (sc.hasNextLine()) { 
            String line = sc.nextLine().trim(); 

            if (line.isEmpty()) { 
                continue; 
            } 

            String[] values = line.split("\\s+"); 
            int[] row = new int[values.length]; 

            for (int j = 0; j < values.length; j++) { 

                if (values[j].equalsIgnoreCase("INF")) { 
                    row[j] = INF; 
                } else { 
                    row[j] = Integer.parseInt(values[j]); 
                } 
            } 

            inputRows.add(row); 
        } 

        sc.close(); 

        if (inputRows.isEmpty()) { 
            return; 
        } 

        int rows = inputRows.size(); 
        int cols = inputRows.get(0).length; 
        int[][] rooms = new int[rows][cols]; 
        Queue<int[]> queue = new LinkedList<>(); 

        for (int i = 0; i < rows; i++) { 
            if (inputRows.get(i).length != cols) { 
                return; 

            } 

            rooms[i] = inputRows.get(i).clone(); 

            for (int j = 0; j < cols; j++) { 
                if (rooms[i][j] == 0) { 
                    queue.offer(new int[]{i, j}); 
                } 
            } 
        } 

        int[] dr = {-1, 1, 0, 0}; 
        int[] dc = {0, 0, -1, 1}; 

        while (!queue.isEmpty()) { 
            int[] curr = queue.poll(); 
            int r = curr[0]; 
            int c = curr[1]; 

            for (int d = 0; d < 4; d++) { 
                int nr = r + dr[d]; 
                int nc = c + dc[d]; 

                if (nr < 0 || nr >= rows || 

                    nc < 0 || nc >= cols) { 
                    continue; 
                } 

                if (rooms[nr][nc] == INF) { 
                    rooms[nr][nc] = rooms[r][c] + 1; 
                    queue.offer(new int[]{nr, nc}); 
                } 
            } 
        } 

        for (int i = 0; i < rows; i++) { 
            for (int j = 0; j < cols; j++) { 
                if (j > 0) { 
                    System.out.print(" "); 
                } 

                System.out.print( 
                    rooms[i][j] == INF ? "INF" : rooms[i][j] 
                ); 
            } 
            System.out.println(); 
        } 
    } 

}

