public class Solution { 

    public static void main(String[] args) { 
        Scanner sc = new Scanner(System.in); 

        int m = sc.nextInt(); 
        int n = sc.nextInt(); 

        char[][] board = new char[m][n]; 

        for (int i = 0; i < m; i++) { 
            String row = sc.next(); 
            board[i] = row.toCharArray(); 
        } 

        sc.close(); 

        Queue<int[]> queue = new ArrayDeque<>(); 

        // Add boundary O cells to the queue. 
        for (int i = 0; i < m; i++) { 
            if (board[i][0] == 'O') { 
                board[i][0] = '#'; 
                queue.offer(new int[]{i, 0}); 
            } 

            if (board[i][n - 1] == 'O') { 
                board[i][n - 1] = '#'; 
                queue.offer(new int[]{i, n - 1}); 
            } 
        } 

        for (int j = 0; j < n; j++) { 
            if (board[0][j] == 'O') { 
                board[0][j] = '#'; 
                queue.offer(new int[]{0, j}); 
            } 

            if (board[m - 1][j] == 'O') { 
                board[m - 1][j] = '#'; 
                queue.offer(new int[]{m - 1, j}); 
            } 
        } 

        int[] dr = {-1, 1, 0, 0}; 
        int[] dc = {0, 0, -1, 1}; 

        // BFS to preserve all boundary-connected O cells. 
        while (!queue.isEmpty()) { 
            int[] cell = queue.poll(); 
            int r = cell[0]; 
            int c = cell[1]; 

            for (int d = 0; d < 4; d++) { 
                int nr = r + dr[d]; 
                int nc = c + dc[d]; 

                if (nr >= 0 && nr < m && 
                    nc >= 0 && nc < n && 
                    board[nr][nc] == 'O') { 

                    board[nr][nc] = '#'; 
                    queue.offer(new int[]{nr, nc}); 
                } 
            } 
        } 

        // Capture surrounded regions and restore safe cells. 
        for (int i = 0; i < m; i++) { 
            for (int j = 0; j < n; j++) { 
                if (board[i][j] == 'O') { 
                    board[i][j] = 'X'; 
                } else if (board[i][j] == '#') { 
                    board[i][j] = 'O'; 
                } 
            } 
        } 
        // Print the modified board. 
        for (int i = 0; i < m; i++) { 
            System.out.println(new String(board[i])); 
        } 
    } 
}

