import java.util.*; 

public class Solution { 

    static int[] parent; 
    static int[] rank; 

    static int find(int x) { 
        if (parent[x] != x) { 
            parent[x] = find(parent[x]); 
        } 
        return parent[x]; 
    } 

    static boolean union(int a, int b) { 
        int rootA = find(a); 
        int rootB = find(b); 

        if (rootA == rootB) { 
            return false; 
        } 

        if (rank[rootA] < rank[rootB]) { 
            parent[rootA] = rootB; 
        } else if (rank[rootA] > rank[rootB]) { 
            parent[rootB] = rootA; 
        } else { 
            parent[rootB] = rootA; 
            rank[rootA]++; 
        } 

        return true; 
    } 

    public static void main(String[] args) { 
        Scanner sc = new Scanner(System.in); 

        int n = sc.nextInt(); 
        int edges = sc.nextInt(); 

        if (edges != n - 1) { 
            System.out.println("false"); 
            sc.close(); 
            return; 
        } 

        parent = new int[n]; 
        rank = new int[n]; 

        for (int i = 0; i < n; i++) { 
            parent[i] = i; 
        } 

        boolean valid = true; 

        for (int i = 0; i < edges; i++) { 
            int u = sc.nextInt(); 
            int v = sc.nextInt(); 

            if (!union(u, v)) { 
                valid = false; 
            } 
        } 

        sc.close(); 

        System.out.println(valid ? "true" : "false"); 
    } 
}

