            } 

            for (int d = 0; d < 4; d++) { 
                int nr = r + dr[d]; 
                int nc = c + dc[d]; 

                if (nr < 0 || nr >= n || nc < 0 || nc >= n) { 
                    continue; 
                } 

                int newTime = Math.max(time, grid[nr][nc]); 

                if (newTime < best[nr][nc]) { 
                    best[nr][nc] = newTime; 
                    pq.offer(new Cell(nr, nc, newTime)); 
                } 
            } 
        } 

        System.out.println(-1); 
    } 
}

