        } else { 
            Matcher matcher = Pattern.compile("\\d+").matcher(raw); 
            if (!matcher.find()) { 
                System.out.println("[]"); 
                return; 
            } 
            n = Integer.parseInt(matcher.group()); 
        } 

        graph = new ArrayList<>(); 
        for (int i = 0; i < n; i++) { 
            graph.add(new ArrayList<>()); 
        } 

        Matcher edgeMatcher = Pattern.compile( 
            "\\[\\s*(\\d+)\\s*,\\s*(\\d+)\\s*\\]" 
        ).matcher(raw); 

        while (edgeMatcher.find()) { 
            int u = Integer.parseInt(edgeMatcher.group(1)); 
            int v = Integer.parseInt(edgeMatcher.group(2)); 

            if (u >= 0 && u < n && v >= 0 && v < n) { 
                graph.get(u).add(v); 
                graph.get(v).add(u); 
            } 
        } 

        discovery = new int[n]; 
        low = new int[n]; 
        visited = new boolean[n]; 
        bridges = new ArrayList<>(); 
        timer = 0; 

        for (int i = 0; i < n; i++) { 
            if (!visited[i]) { 
                dfs(i, -1); 
            } 
        } 

        bridges.sort((a, b) -> { 
            if (a[0] != b[0]) { 
                return Integer.compare(a[0], b[0]); 
            } 
            return Integer.compare(a[1], b[1]); 
        }); 

        StringBuilder result = new StringBuilder("["); 
        for (int i = 0; i < bridges.size(); i++) { 
            if (i > 0) { 
                result.append(","); 
            } 
            result.append("[") 
                  .append(bridges.get(i)[0]) 
                  .append(",") 
                  .append(bridges.get(i)[1]) 
                  .append("]"); 
        } 
        result.append("]"); 

        System.out.println(result); 
    } 

    static void dfs(int u, int parent) { 
        visited[u] = true; 
        discovery[u] = low[u] = ++timer; 

        for (int v : graph.get(u)) { 
            if (v == parent) { 
                continue; 
            } 

            if (!visited[v]) { 
                dfs(v, u); 
                low[u] = Math.min(low[u], low[v]); 

                if (low[v] > discovery[u]) { 
                    bridges.add(new int[]{ 
                        Math.min(u, v), 
                        Math.max(u, v) 
                    }); 
                } 
            } else { 
                low[u] = Math.min(low[u], discovery[v]); 
            } 
        } 
    } 
}

