        StringBuilder input = new StringBuilder(); 

        while (sc.hasNextLine()) { 
            input.append(sc.nextLine()).append(" "); 
        } 
        sc.close(); 

        String raw = input.toString(); 

        Matcher amountMatcher = 
            Pattern.compile("\\bamount\\s*=\\s*(\\d+)").matcher(raw); 

        int amount; 
        List<Integer> coins = new ArrayList<>(); 

        if (amountMatcher.find()) { 
            amount = Integer.parseInt(amountMatcher.group(1)); 

            int coinsIndex = raw.indexOf("coins"); 
            int openBracket = raw.indexOf('[', coinsIndex); 
            int closeBracket = raw.indexOf(']', openBracket); 

            if (coinsIndex >= 0 && openBracket >= 0 && closeBracket 
>= 0) { 
                Matcher coinMatcher = Pattern.compile("\\d+") 
                    .matcher(raw.substring(openBracket + 1, closeBracket)); 

                while (coinMatcher.find()) { 
                    coins.add(Integer.parseInt(coinMatcher.group())); 
                } 
            } 
        } else { 
            Matcher matcher = Pattern.compile("\\d+").matcher(raw); 
            List<Integer> values = new ArrayList<>(); 

            while (matcher.find()) { 
                values.add(Integer.parseInt(matcher.group())); 
            } 

            if (values.isEmpty()) { 
                System.out.println(-1); 
                return; 
            } 

            int count = values.get(0); 

            if (values.size() >= count + 2) { 
                for (int i = 1; i <= count; i++) { 
                    coins.add(values.get(i)); 
                } 
                amount = values.get(count + 1); 
            } else { 
                for (int value : values) { 
                    coins.add(value); 
                } 
                amount = 0; 
            } 
        } 

        if (amount == 0) { 
            System.out.println(0); 
            return; 
        } 

        int[] dp = new int[amount + 1]; 
        Arrays.fill(dp, amount + 1); 
        dp[0] = 0; 

        for (int current = 1; current <= amount; current++) { 
            for (int coin : coins) { 
                if (coin > 0 && coin <= current) { 
                    dp[current] = Math.min( 
                        dp[current], 
                        dp[current - coin] + 1 
                    ); 
                } 
            } 
        } 

        System.out.println(dp[amount] > amount ? -1 : dp[amount]); 
    } 
}

