import java.util.*; 

public class Solution { 
    public static void main(String[] args) { 
        Scanner sc = new Scanner(System.in); 
        List<String> lines = new ArrayList<>(); 

        while (sc.hasNextLine()) { 
            String line = sc.nextLine().trim(); 
            if (!line.isEmpty()) { 
                lines.add(line); 
            } 
        } 
        sc.close(); 

        if (lines.isEmpty()) { 
            System.out.println(false); 
            return; 
        } 

        String s = lines.get(0); 
        Set<String> wordDict = new HashSet<>(); 

        int startIndex = 1; 

        // Standard format: string, dictionary size, then dictionary words. 
        if (lines.size() >= 2 && lines.get(1).matches("\\d+")) { 
            int n = Integer.parseInt(lines.get(1)); 
            startIndex = 2; 

            for (int i = startIndex; i < lines.size() && i < startIndex + n; 
i++) { 
                wordDict.add(lines.get(i)); 
            } 
        } else { 
            // Irregular format: string followed directly by dictionary 
// words. 
            // A trailing digit may represent the omitted dictionary size. 
            if (s.matches(".*\\d+$")) { 
                s = s.replaceFirst("\\d+$", ""); 
            } 

            for (int i = startIndex; i < lines.size(); i++) { 
                wordDict.add(lines.get(i)); 
            } 

            // Handle a single-line malformed case such as "aaa aab". 
            if (lines.size() == 1) { 
                String[] parts = lines.get(0).split("\\s+"); 
                if (parts.length > 1) { 
                    s = parts[0]; 
                    for (int i = 1; i < parts.length; i++) { 
                        wordDict.add(parts[i]); 
                    } 
                } 
            } 
        } 

        int len = s.length(); 
        boolean[] dp = new boolean[len + 1]; 
        dp[0] = true; 

        int maxWordLength = 0; 
        for (String word : wordDict) { 
            maxWordLength = Math.max(maxWordLength, 
word.length()); 
        } 

        for (int i = 1; i <= len; i++) { 
            for (int j = Math.max(0, i - maxWordLength); j < i; j++) { 
                if (dp[j] && wordDict.contains(s.substring(j, i))) { 
                    dp[i] = true; 
                    break; 
                } 
            } 
        } 

        System.out.println(dp[len]); 
    } 
}

