            return; 
        } 

        int n = values.get(0); 

        if (n <= 0 || values.size() < 1 + 3 * n + 3) { 
            System.out.println(false); 
            return; 
        } 

        int[][] triplets = new int[n][3]; 
        int index = 1; 


        for (int i = 0; i < n; i++) { 
            for (int j = 0; j < 3; j++) { 
                triplets[i][j] = values.get(index++); 
            } 
        } 

        int[] target = new int[3]; 

        for (int i = 0; i < 3; i++) { 
            target[i] = values.get(index++); 
        } 

        System.out.println(mergeTriplets(triplets, target)); 
    } 

    public static boolean mergeTriplets(int[][] triplets, int[] target) { 
        boolean first = false; 
        boolean second = false; 
        boolean third = false; 

        for (int[] triplet : triplets) { 
            if (triplet[0] > target[0] || 
                triplet[1] > target[1] || 

                triplet[2] > target[2]) { 
                continue; 
            } 

            if (triplet[0] == target[0]) first = true; 
            if (triplet[1] == target[1]) second = true; 
            if (triplet[2] == target[2]) third = true; 
        } 

        return first && second && third; 
    } 
}

