        String s = sc.nextLine().trim(); 

        int minOpen = 0; 
        int maxOpen = 0; 

        for (int i = 0; i < s.length(); i++) { 
            char ch = s.charAt(i); 

            if (ch == '(') { 
                minOpen++; 
                maxOpen++; 
            } else if (ch == ')') { 
                minOpen--; 
                maxOpen--; 
            } else if (ch == '*') { 
                minOpen--;  // '*' acts as ')' 
                maxOpen++;  // '*' acts as '(' 
            } 

            if (maxOpen < 0) { 
                System.out.println(false); 
                sc.close(); 
                return; 
            } 

            minOpen = Math.max(minOpen, 0); 
        } 

        System.out.println(minOpen == 0); 
        sc.close(); 
    } 
}

