        for (int i = 0; i < n; i++) { 
            for (int j = 0; j < n; j++) { 
                matrix[i][j] = sc.nextInt(); 
            } 
        } 

        // Step 1: Transpose the matrix 
        for (int i = 0; i < n; i++) { 
            for (int j = i + 1; j < n; j++) { 
                int temp = matrix[i][j]; 
                matrix[i][j] = matrix[j][i]; 
                matrix[j][i] = temp; 
            } 
        } 

        // Step 2: Reverse each row 
        for (int i = 0; i < n; i++) { 
            int left = 0; 
            int right = n - 1; 

            while (left < right) { 
                int temp = matrix[i][left]; 
                matrix[i][left] = matrix[i][right]; 
                matrix[i][right] = temp; 

                left++; 
                right--; 
            } 
        } 

        // Print the rotated matrix 
        for (int i = 0; i < n; i++) { 
            for (int j = 0; j < n; j++) { 
                if (j > 0) { 
                    System.out.print(" "); 
                } 
                System.out.print(matrix[i][j]); 
            } 
            System.out.println(); 
        } 

