                firstRowZero = true; 
                break; 
            } 
        } 

        // Check whether the first column contains zero 
        for (int i = 0; i < m; i++) { 
            if (matrix[i][0] == 0) { 
                firstColZero = true; 
                break; 
            } 
        } 

        // Mark rows and columns using the first row and column 
        for (int i = 1; i < m; i++) { 
            for (int j = 1; j < n; j++) { 
                if (matrix[i][j] == 0) { 
                    matrix[i][0] = 0; 
                    matrix[0][j] = 0; 
                } 
            } 
        } 

        // Set marked rows to zero 
        for (int i = 1; i < m; i++) { 
            if (matrix[i][0] == 0) { 
                for (int j = 1; j < n; j++) { 
